+ * @returns その親の名前と index。画面構造に無ければ（部品定義の中のノードも）「無し」
+ */
+export function childPositionNamed(
+  state: EditorState,
+  name: string,
+): Option<ChildPosition> {
+  return DesignDocument.findChildPosition(EditorState.document(state), name);
+}
+
+/**
